import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateCapabilityMatrix } from "../src/capability.ts";

const here = dirname(fileURLToPath(import.meta.url));
const matrixPath = resolve(here, "../../../specs/adapter-capabilities.v0.json");
const unapprovedLocator = "https://evidence.example.invalid/trace/42";

const frozen = () => JSON.parse(readFileSync(matrixPath, "utf8"));
const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value));

test("capability matrices reject non-forbidden locators outside approved source surfaces", () => {
  const declared = frozen();
  const declaredResult = validateCapabilityMatrix(declared);
  assert.equal(
    declaredResult.ok,
    true,
    `declared capability locators must remain valid: ${declaredResult.errors.join("; ")}`
  );

  for (const row of declared.rows) {
    for (const [runtimeId, cell] of Object.entries(row.runtimes) as [string, any][]) {
      const candidate = clone(declared);
      const candidateRow = candidate.rows.find((entry: any) => entry.event_group === row.event_group);
      candidateRow.runtimes[runtimeId].evidence_locator = unapprovedLocator;

      const result = validateCapabilityMatrix(candidate);
      assert.equal(
        result.ok,
        false,
        `${row.event_group}/${runtimeId}/${cell.source_class} accepted an unapproved, non-forbidden locator`
      );
    }
  }
});
